backScript.script:
def cls = requestData.get("class_ref")
if (cls != null && !cls.toString().isEmpty()) {
  def rows = daoService.querySql("jiapei_student_info", "select count(*) as cnt from jiapei_student_info where class_ref = '" + cls + "' and deleted_flag = 'N'")
  long cnt = 0
  if (rows != null && !rows.isEmpty() && rows.get(0).get("cnt") != null) {
    cnt = Long.parseLong(rows.get(0).get("cnt").toString())
  }
  def idv = requestData.get("id")
  long delta = (idv == null || idv.toString().isEmpty()) ? 1L : 0L
  daoService.saveOrUpdate("jiapei_class_info", ["id": cls.toString(), "student_count": cnt + delta])
}

def st = requestData.get("start_time")
def et = requestData.get("end_time")
if (st != null && et != null && !st.toString().isEmpty() && !et.toString().isEmpty()) {
  if (et.toString() <= st.toString()) {
    throw new RuntimeException("结束日期必须晚于开始日期")
  }
}
